/// @sort 32
uniform float A = 1.0;
/// @sort 32
uniform float3 V = float3(1.0, 2.0, 3.0);
// Every statement form a 1.x Graph had: declarations, assignments, member writes, calls, `if` / `else` with one comparison, regions.
/// @name M_LpGStatements
export void M_LpGStatements(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Local = A * 2.0;
    float3 Tinted = V * Local;
    Tinted.x = 0.5;
    #pragma region Branch
    if (A > 0.5)
    {
        Color = Tinted;
    }
    else
    {
        Color = float3(0.0, 0.0, 0.0);
    }
    #pragma endregion
    float t = UE.Time();
    Color = Color * sin(t);
    Base.EmissiveColor = Color;
}
